import React from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import L from 'leaflet';

const MapComponent = ({ vehicles, stations }) => {
  // Créer des icônes personnalisées pour les véhicules et les stations
  const vehicleIcon = L.icon({
    iconUrl: 'path/to/vehicle-icon.png', // Remplacez par le chemin vers votre icône de véhicule
    iconSize: [25, 41],
    iconAnchor: [12, 41],
    popupAnchor: [1, -34],
    shadowSize: [41, 41],
  });

  const stationIcon = L.icon({
    iconUrl: 'path/to/station-icon.png', // Remplacez par le chemin vers votre icône de station
    iconSize: [25, 41],
    iconAnchor: [12, 41],
    popupAnchor: [1, -34],
    shadowSize: [41, 41],
  });

  return (
    <MapContainer center={[51.505, -0.09]} zoom={13} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      />
      {vehicles.map((vehicle, index) => (
        <Marker key={index} position={vehicle.location} icon={vehicleIcon}>
          <Popup>
            <b>{vehicle.name}</b><br />
            Battery: {vehicle.battery_capacity} kWh
          </Popup>
        </Marker>
      ))}
      {stations.map((station, index) => (
        <Marker key={index} position={station.location} icon={stationIcon}>
          <Popup>
            <b>{station.name}</b><br />
            Charging Speed: {station.charging_speed} kW
          </Popup>
        </Marker>
      ))}
    </MapContainer>
  );
};

export default MapComponent;
